import{_ as o,C as r,c as s,o as i,a3 as n,G as a}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Journals","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/get-started/journals.md","filePath":"master/finance/get-started/journals.md","lastUpdated":1792041590000}'),l={name:"master/finance/get-started/journals.md"};function c(u,e,d,h,g,m){const t=r("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=n('<h1 id="journals" tabindex="-1">Journals <a class="header-anchor" href="#journals" aria-label="Permalink to &quot;Journals&quot;">​</a></h1><p>A journal is a book in which you record one kind of entry. Sales invoices go in the Customer Invoices journal. Supplier bills go in Vendor Bills. Money in your bank goes in a Bank journal. Every invoice, bill, payment and entry belongs to exactly one journal.</p><blockquote><p><strong>In simple words:</strong> A journal is a folder for one kind of accounting entry. Each folder has its own numbering and its own default accounts.</p></blockquote><h2 id="when-to-use-this-page" tabindex="-1">When to use this page <a class="header-anchor" href="#when-to-use-this-page" aria-label="Permalink to &quot;When to use this page&quot;">​</a></h2><ul><li>You open a new bank account or a cash box and need a journal for it.</li><li>You want a separate numbering for credit notes or payments.</li><li>You want to change the account a journal uses by default.</li></ul><h2 id="open-the-page" tabindex="-1">Open the page <a class="header-anchor" href="#open-the-page" aria-label="Permalink to &quot;Open the page&quot;">​</a></h2><p>Go to <code>Accounting → Configurations → Accounting → Journals</code>. This page exists only in the <strong>Accounting</strong> app. In the Invoices app you pick journals on documents, but you cannot configure them.</p>',7)),a(t,{src:"/images1/finance/journals_list.png",alt:"Accounting → Configurations → Accounting → Journals, showing the six default journals"}),e[1]||(e[1]=n('<h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list shows <strong>Name</strong>, <strong>Type</strong>, <strong>Code</strong>, <strong>Currency</strong> and <strong>Created By</strong>. The tabs <strong>All</strong>, <strong>Sales</strong>, <strong>Purchases</strong>, <strong>Cash</strong>, <strong>Bank</strong> and <strong>Miscellaneous</strong> filter by type. A set-up company has six journals:</p><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Code</th></tr></thead><tbody><tr><td>Customer Invoices</td><td>Sale</td><td>INV</td></tr><tr><td>Vendor Bills</td><td>Purchase</td><td>BILL</td></tr><tr><td>Miscellaneous Operations</td><td>Miscellaneous</td><td>MISC</td></tr><tr><td>Exchange Difference</td><td>Miscellaneous</td><td>EXCH</td></tr><tr><td>Bank Transactions</td><td>Bank</td><td>BANK</td></tr><tr><td>Cash Transactions</td><td>Cash</td><td>CASH</td></tr></tbody></table><h2 id="journal-types" tabindex="-1">Journal types <a class="header-anchor" href="#journal-types" aria-label="Permalink to &quot;Journal types&quot;">​</a></h2><ul><li><strong>Sale:</strong> customer invoices and credit notes.</li><li><strong>Purchase:</strong> vendor bills and refunds.</li><li><strong>Bank:</strong> payments through a bank account.</li><li><strong>Cash:</strong> payments in cash.</li><li><strong>Credit Card:</strong> payments by company card.</li><li><strong>Miscellaneous:</strong> manual entries and exchange differences.</li></ul><h2 id="create-a-journal" tabindex="-1">Create a journal <a class="header-anchor" href="#create-a-journal" aria-label="Permalink to &quot;Create a journal&quot;">​</a></h2><ol><li>Go to <code>Accounting → Configurations → Accounting → Journals</code>.</li><li>Click <strong>New Journal</strong>.</li><li>Fill in <strong>General Information</strong> on the right, then the tabs on the left.</li><li>Click <strong>Create</strong>.</li></ol>',7)),a(t,{src:"/images1/finance/journal_form.png",alt:"New Journal form with Name Main Bank, Type Bank, Code MBNK and a Default Account chosen"}),e[2]||(e[2]=n('<h3 id="general-information" tabindex="-1">General Information <a class="header-anchor" href="#general-information" aria-label="Permalink to &quot;General Information&quot;">​</a></h3><ul><li><strong><em>Name:</em></strong> The name shown on cards and pickers, such as <code>Main Bank</code>. Required.</li><li><strong><em>Type:</em></strong> Sale, Purchase, Cash, Bank, Credit Card or Miscellaneous. Required. The type decides which other fields appear.</li><li><strong><em>Company:</em></strong> The current company. You cannot change it.</li></ul><h3 id="journal-entries-tab-accounting-information" tabindex="-1">Journal Entries tab: Accounting Information <a class="header-anchor" href="#journal-entries-tab-accounting-information" aria-label="Permalink to &quot;Journal Entries tab: Accounting Information&quot;">​</a></h3><ul><li><strong><em>Dedicated Credit Note Sequence:</em></strong> Sale and Purchase journals only. Turn on to number credit notes separately from invoices.</li><li><strong><em>Dedicated Payment Sequence:</em></strong> Bank, Cash and Credit Card journals only. Turn on to number payments separately from other entries.</li><li><strong><em>Sort:</em></strong> The short code of the journal, such as <code>MBNK</code>. The form calls it <strong>Sort</strong>. The list shows it in the <strong>Code</strong> column.</li><li><strong><em>Currency:</em></strong> An active currency for the journal. Leave it empty to use the company currency. On Bank, Cash and Credit Card journals, changing it resets the payment lines to the default manual method.</li><li><strong><em>Color:</em></strong> A colour for the journal.</li><li><strong><em>Default Account:</em></strong> The account used for the journal&#39;s main lines. Required.</li><li><strong><em>Profit Account:</em></strong> For Sale, Bank and Cash journals. An income account for gains.</li><li><strong><em>Loss Account:</em></strong> For Purchase, Bank and Cash journals. An expense account for losses.</li><li><strong><em>Suspense Account:</em></strong> For Bank, Cash and Credit Card journals. A holding account for amounts not yet sorted out.</li><li><strong><em>Bank Account:</em></strong> Bank journals only, under <strong>Bank Account Number</strong>. Choose the company&#39;s bank account. Add accounts first in <a href="./../payments/bank-accounts.html">Bank accounts</a>.</li></ul><h3 id="incoming-payments-and-outgoing-payments-tabs" tabindex="-1">Incoming Payments and Outgoing Payments tabs <a class="header-anchor" href="#incoming-payments-and-outgoing-payments-tabs" aria-label="Permalink to &quot;Incoming Payments and Outgoing Payments tabs&quot;">​</a></h3><p>These tabs show for Bank, Cash and Credit Card journals. Click <strong>Add Line</strong> to add a payment method line.</p><ul><li><strong><em>Payment Method:</em></strong> The way money moves, for example Manual. Required.</li><li><strong><em>Display Name:</em></strong> The name people see when they pick the method on a payment. Required.</li><li><strong><em>Outstanding Receipts Accounts</em></strong> (incoming) or <strong><em>Outstanding Payments Accounts</em></strong> (outgoing): Where the amount waits after you confirm a payment and before it is in the bank.</li></ul><h3 id="advanced-settings-tab" tabindex="-1">Advanced Settings tab <a class="header-anchor" href="#advanced-settings-tab" aria-label="Permalink to &quot;Advanced Settings tab&quot;">​</a></h3><ul><li><strong><em>Allowed Accounts:</em></strong> Limit the accounts that can be used in this journal. Leave empty for no limit.</li><li><strong><em>Auto Check on Post:</em></strong> Mark entries as checked when you post them.</li><li><strong><em>Communication Type</em></strong> and <strong><em>Communication Standard</em>:</strong> Sale journals only. They choose how the payment reference on invoices is built: <strong>Open</strong>, <strong>Base on Partner</strong> or <strong>Base on Invoice</strong>, in the <strong>Aureus</strong> or <strong>European</strong> format.</li></ul><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>Your company opens a second bank account. Create a journal named <code>Savings Bank</code>, <strong>Type</strong> <code>Bank</code>, <strong>Sort</strong> <code>SAV</code>. Pick the savings account as <strong>Default Account</strong> and the bank account under <strong>Bank Account Number</strong>. On a payment you can now choose <code>Savings Bank</code> as the journal.</p><h2 id="delete-a-journal" tabindex="-1">Delete a journal <a class="header-anchor" href="#delete-a-journal" aria-label="Permalink to &quot;Delete a journal&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A journal that is in use cannot be deleted. Aureus shows &quot;Journal deletion failed&quot;. Keep it, or stop using it.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./chart-of-accounts.html">Chart of accounts</a></li><li><a href="./default-accounts.html">Default accounts</a></li><li><a href="./../payments/bank-accounts.html">Bank accounts</a></li><li><a href="./../payments/register-payment.html">Register a payment</a></li></ul>',15))])}const y=o(l,[["render",c]]);export{f as __pageData,y as default};
